```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, count(*) AS n, round(avg(value),2) AS avg_v, round(max(value),2) AS max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'geo%' AND metric IN ('k8s.container.ready','k8s.container.restarts') GROUP BY metric ORDER BY metric",
          "claim": "The geo pod reports container ready=0 throughout the abnormal window, with restarts climbing to 6."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'geo' OR span_name = 'geo.Geo/Nearby' GROUP BY ALL ORDER BY 1,2,3,4",
          "claim": "No geo server spans appear in the abnormal window; every geo.Geo/Nearby call is a failed client span from search."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n FROM normal_traces WHERE service_name = 'geo' GROUP BY ALL",
          "claim": "In the normal period geo served about 620 Nearby server spans, so its absence is a real change."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, round(avg(duration)/1e6,2) AS avg_ms FROM abnormal_traces WHERE span_name = 'geo.Geo/Nearby' OR span_name = 'search.Search/Nearby' GROUP BY ALL ORDER BY 1,2,3,4",
          "claim": "All 886 search calls to geo.Geo/Nearby fail in about 0.02 ms, and search's own Nearby server spans all return Error."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'frontend' AND (span_name = 'search.Search/Nearby' OR span_name = 'HTTP /hotels') GROUP BY ALL ORDER BY 1,2,3,4,5",
          "claim": "Frontend's search client calls and its /hotels server spans all error, with HTTP 500 on /hotels."
        }
      ]
    }
  ]
}
```

